import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    m = int(input_data[1])
    s = input_data[2]
    t = input_data[3]

    if '*' not in s:
        if s == t:
            print("YES")
        else:
            print("NO")
        return

    parts = s.split('*')
    prefix = parts[0]
    suffix = parts[1]

    if len(t) < len(prefix) + len(suffix):
        print("NO")
        return

    if t.startswith(prefix) and t.endswith(suffix):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
